#include "MainComponent.h"
namespace {juce::String u(const char* s){return juce::String::fromUTF8(s);}juce::String summary(const vocal::EqRecommendation& r){const auto& e=r.suggested;return u("ĐỀ XUẤT EQ GIỌNG TÔI\n\nGiọng rõ đã phân tích: ")+juce::String(r.voicedSeconds,1)+u(" giây\nLow-cut: ")+juce::String(e.highPass,0)+u(" Hz — giữ nền giọng trầm\nĐộ ấm / low shelf: ")+juce::String(e.warmth,1)+u(" dB\nĐộ rõ / 3,2 kHz: ")+juce::String(e.presence,1)+u(" dB\nLàm dịu gắt: ")+juce::String(e.deharsh*100,0)+u("%\nDe-esser: ")+juce::String(e.deEss*100,0)+u("%\nBù mức A/B ước tính: ")+juce::String(r.matchDb,1)+u(" dB\n\n")+u(r.message.c_str())+u("\n\nĐây là gợi ý nhẹ từ bản thu, không phải EQ chuẩn cho mọi bài. Không đổi nốt hay kéo giọng lên cao; dùng Antares cho phần đó. Beat, vang, compressor và Key/Scale được giữ nguyên.");}}
void StudioMain::recordAutoEq(){if(isBusy())return;if(eqRecording){record();return;}if(!canEdit()){eqStatus=u("Dừng bản thu/phát hiện tại trước khi thu mẫu cân EQ.");return;}cancelAutoEq();eqSuggestion={};record();if(engine.isRecording()){eqRecording=true;eqStatus=u("ĐANG THU MICRO GỐC\n\nCứ mở YouTube trong tool và hát một bài có đoạn thấp, cao và hát mạnh. Hát ít nhất vài câu rõ, nên từ 10 giây trở lên. Bấm Dừng thu để tự phân tích.\n\nUPod Pro: Mic with DSP OFF, Mixing OFF; dùng tai nghe. Phần mềm lưu micro trước EQ/vang/Antares, nhưng không loại được nhạc hoặc DSP đã trộn vào từ phần cứng.");}else eqStatus=userStatus();}
void StudioMain::analyseAutoEq(){if(!canEdit()||selected<0){eqStatus=u("Dừng thu và chọn một bản giọng khô của chính bạn. Có thể thu một bài ngay tại đây.");return;}cancelAutoEq();eqSuggestion={};eqBefore=eqRestore=eqLast=engine.eqSettings();eqSession=projectFile.getFullPathName();setBusy(true,u("Đang phân tích độ ù, chói và tiếng s từ micro gốc…"));eqStatus=u("Đang phân tích các đoạn trải đều bài hát, chưa thay EQ.");cancelExport=false;exportProgress=0;const int index=selected;eqSource=index;eqSourceFile=engine.getTracks()[static_cast<std::size_t>(index)]->originalFile.getFullPathName();auto result=std::make_shared<vocal::EqRecommendation>();auto ok=std::make_shared<juce::Result>(juce::Result::ok());juce::Component::SafePointer<StudioMain> safe(this);runJob([this,index,result,ok]{*ok=engine.analyseEqTrack(index,*result,cancelExport,exportProgress);},[safe,result,ok]{if(!safe)return;if(safe->cancelExport||ok->failed()){safe->eqStatus=safe->cancelExport?u("Đã hủy; EQ đang dùng không thay đổi."):ok->getErrorMessage();safe->eqSuggestion={};return;}safe->eqSuggestion=*result;safe->eqStatus=summary(*result);safe->status(u("Đã tính EQ đề xuất. Bấm A/B để nghe, Lưu B khi phù hợp."));});}
void StudioMain::previewAutoEq(bool proposed){if(isBusy()||!eqSuggestion.valid)return;if(eqSession!=projectFile.getFullPathName()){eqPreview=false;eqSuggestion={};eqStatus=u("Phiên thu đã đổi. Phân tích lại hoặc nạp EQ riêng đã lưu.");return;}if(!vocal::sameEq(engine.eqSettings(),eqLast)){eqPreview=false;eqSuggestion={};eqStatus=u("EQ đã được chỉnh ở nơi khác. Giữ thiết lập mới; phân tích lại để nghe A/B.");return;}eqLast=proposed?eqSuggestion.suggested:eqBefore;engine.applyEq(eqLast);eqPreview=true;syncKnobs();status(proposed?u("B: nghe EQ đề xuất, có bù mức ước tính."):u("A: nghe EQ trước khi phân tích."));}
void StudioMain::cancelAutoEq(){if(engine.isEqListening())engine.stop();if(isBusy())cancelExport=true;if(eqPreview&&eqSession==projectFile.getFullPathName()&&vocal::sameEq(engine.eqSettings(),eqLast))engine.applyEq(eqRestore);eqPreview=false;eqLast=engine.eqSettings();}
void StudioMain::saveAutoEq(){if(isBusy()||!eqSuggestion.valid||eqSession!=projectFile.getFullPathName())return;if(!vocal::sameEq(engine.eqSettings(),eqLast)){eqStatus=u("EQ đã đổi; phân tích lại trước khi lưu B.");return;}engine.applyEq(eqSuggestion.suggested);eqRestore=eqLast=eqSuggestion.suggested;eqPreview=false;auto* obj=new juce::DynamicObject;obj->setProperty("version",1);obj->setProperty("highPass",eqLast.highPass);obj->setProperty("warmth",eqLast.warmth);obj->setProperty("presence",eqLast.presence);obj->setProperty("deharsh",eqLast.deharsh);obj->setProperty("deEss",eqLast.deEss);obj->setProperty("inputDb",eqLast.inputDb);preferences.getUserSettings()->setValue("personalEq",juce::JSON::toString(juce::var(obj)));preferences.saveIfNeeded();syncKnobs();save();eqStatus=summary(eqSuggestion)+u("\n\nĐÃ LƯU B · Preset giọng của bạn nằm trên máy và EQ hiện tại được lưu cùng phiên thu. Bấm Dùng EQ đã lưu để áp dụng cho phiên khác.");}
void StudioMain::loadAutoEq(){if(isBusy()||engine.isRecording())return;const auto data=juce::JSON::parse(preferences.getUserSettings()->getValue("personalEq"));vocal::EqSettings eq{static_cast<float>(data["highPass"]),static_cast<float>(data["warmth"]),static_cast<float>(data["presence"]),static_cast<float>(data["deharsh"]),static_cast<float>(data["deEss"]),static_cast<float>(data["inputDb"])};if(!data.isObject()||static_cast<int>(data["version"])!=1||!eq.valid()){eqStatus=u("Chưa có EQ riêng hợp lệ. Thu một bài hoặc chọn bản micro khô để phân tích trước.");return;}cancelAutoEq();eqBefore=engine.eqSettings();eqSource=-1;eqSourceFile={};eqRestore=eqLast=eq;eqSession=projectFile.getFullPathName();eqSuggestion={};eqSuggestion.valid=true;eqSuggestion.suggested=eq;eqSuggestion.message="Đã nạp EQ riêng đã lưu; không phân tích lại bài hiện tại.";engine.applyEq(eq);syncKnobs();save();eqStatus=u("Đã áp dụng EQ riêng đã lưu. Có thể hát để nghe, hoặc phân tích một bản giọng mới khi đổi micro, khoảng cách hoặc phòng. Không tự đổi tone/Antares.");}

void StudioMain::listenAutoEq(){if(isBusy()||engine.isRecording())return;if(engine.isEqListening()){engine.stop();return;}const int index=eqSource>=0&&eqSession==projectFile.getFullPathName()?eqSource:selected;if(eqSource>=0&&(!juce::isPositiveAndBelow(index,static_cast<int>(engine.getTracks().size()))||engine.getTracks()[static_cast<std::size_t>(index)]->originalFile.getFullPathName()!=eqSourceFile)){eqStatus=u("Bản giọng đã đổi. Chọn lại và phân tích trước khi nghe A/B.");return;}pauseMusicForEq();const auto result=engine.auditionOriginal(index);if(result.failed())eqStatus=result.getErrorMessage();else status(u("Đang nghe riêng WAV micro gốc qua FX hiện tại. Bấm A/B để so EQ; YouTube đã tạm dừng, micro kiểm âm tạm tắt trong lúc nghe."));}

void StudioMain::autoMixVocal(){
    if(!canEdit()){status(u("Dừng phát/thu trước khi tự mix."));return;}
    if(!juce::isPositiveAndBelow(selected,static_cast<int>(engine.getTracks().size()))||!engine.getTracks()[static_cast<std::size_t>(selected)]->vocal){status(u("Thu giọng hoặc chọn một track vocal khô trước khi tự mix."));return;}
    cancelAutoEq();eqSuggestion={};eqSource=-1;mixReady=false;
    mixBefore=engine.vocalSettings();mixSession=projectFile.getFullPathName();
    const int index=selected;const auto source=engine.getTracks()[static_cast<std::size_t>(index)]->originalFile;
    const auto session=mixSession;
    cancelExport=false;exportProgress=0;
    setBusy(true,u("Đang phân tích và tự mix vocal…"));
    auto result=std::make_shared<vocal::MixRecommendation>();
    auto ok=std::make_shared<juce::Result>(juce::Result::ok());
    juce::Component::SafePointer<StudioMain> safe(this);
    runJob([this,index,result,ok]{*ok=engine.analyseMixTrack(index,*result,cancelExport,exportProgress);},[safe,index,source,session,result,ok]{
        if(!safe)return;
        if(safe->cancelExport||ok->failed()){safe->status(safe->cancelExport?u("Đã hủy tự mix; giữ thiết lập cũ."):ok->getErrorMessage());return;}
        if(session!=safe->projectFile.getFullPathName()||!juce::isPositiveAndBelow(index,static_cast<int>(safe->engine.getTracks().size()))||safe->engine.getTracks()[static_cast<std::size_t>(index)]->originalFile!=source){safe->status(u("Bản thu đã đổi; chọn lại để tự mix."));return;}
        safe->mixAfter=result->settings;safe->mixReady=true;
        safe->engine.applyVocalSettings(safe->mixAfter);safe->syncKnobs();safe->save();
        safe->status(u(result->message.c_str())+u("\nMức giọng hoạt động: ")+juce::String(result->activeRmsDb,1)+" dBFS"+u(" · Nén: ")+juce::String(result->settings.ratio,1)+":1"+u(" · Low-cut: ")+juce::String(result->settings.highPassHz,0)+" Hz");
    });
}
void StudioMain::previewAutoMix(bool after){
    if(isBusy()||engine.isRecording()||!hasAutoMix())return;
    if(eqPreview)cancelAutoEq();eqSuggestion={};
    engine.applyVocalSettings(after?mixAfter:mixBefore);syncKnobs();save();
    status(after?u("B · Bản tự mix. Antares giữ nguyên."):u("A · Thiết lập trước khi tự mix. Antares giữ nguyên."));
}
